const icon = (name) => `<svg aria-hidden="true"><use href="#${name}"/></svg>`;
const cta = `<section class="section"><div class="container"><div class="cta-block"><h2>آماده‌ای پرسونال برندت را جدی‌تر بسازی؟</h2><p>از شناخت جایگاه امروزت شروع کن و برای قدم بعدی‌ات برنامه داشته باش.</p><a class="btn btn-accent" href="#/signup">شروع رایگان ${icon('arrow')}</a></div></div></section>`;
const featureCards = `<div class="feature-grid"><article class="feature-card"><span class="feature-icon">${icon('target')}</span><h3>تحلیل دقیق برند</h3><p>از جایگاه تخصصی و کیفیت محتوا تا اعتمادسازی، بدان کجای مسیر ایستاده‌ای و چه چیزی را باید بهتر کنی.</p><a href="#/features" class="more">بیشتر بدانید ${icon('arrow')}</a></article><article class="feature-card"><span class="feature-icon">${icon('idea')}</span><h3>ایده‌هایی که به تو می‌آیند</h3><p>به‌جای پیشنهادهای تکراری، ایده‌های محتوایی متناسب با تخصص، مخاطب و هدف صفحه‌ات ببین.</p><a href="#/features" class="more">بیشتر بدانید ${icon('arrow')}</a></article><article class="feature-card"><span class="feature-icon">${icon('chart')}</span><h3>نقشه راه قابل اجرا</h3><p>از عیب‌یابی تا اجرا؛ قدم‌های کوچک و اولویت‌بندی‌شده برای رشد پایدار برند شخصی‌ات بردار.</p><a href="#/features" class="more">بیشتر بدانید ${icon('arrow')}</a></article></div>`;
const steps = `<div class="steps"><div class="step-card"><div class="step-num">01</div><h3>کسب‌وکارت را معرفی کن</h3><p>حوزه تخصص، مخاطب هدف و هدفی را که از تولید محتوا داری مشخص کن.</p></div><div class="step-card"><div class="step-num">02</div><h3>جایگاهت را بشناس</h3><p>تصویر روشنی از نقاط قوت و فرصت‌های بهبود برند شخصی‌ات بگیر.</p></div><div class="step-card"><div class="step-num">03</div><h3>با برنامه رشد کن</h3><p>سراغ اولویت‌های نقشه راه و ایده‌های محتوا برو و پیشرفتت را دنبال کن.</p></div></div>`;
const faq = `<div class="faq-list"><details><summary>برندیار برای چه کسانی مناسب است؟</summary><p>برای مدرس‌ها، مربی‌ها و تولیدکنندگان محتوای آموزشی که می‌خواهند در اینستاگرام برند شخصی مشخص‌تری بسازند و محتوایی هدفمندتر منتشر کنند.</p></details><details><summary>برای شروع باید چند دنبال‌کننده داشته باشم؟</summary><p>برای شروع به عدد مشخصی نیاز نیست. مسیر پیشنهادی محصول برای صفحه‌های آموزشی در حال رشد طراحی شده است.</p></details><details><summary>آیا استفاده از محصول رایگان است؟</summary><p>طرح شروع رایگان در طراحی محصول پیش‌بینی شده است. جزئیات فعال‌سازی و محدودیت‌ها هنگام راه‌اندازی سرویس نهایی اعلام می‌شود.</p></details><details><summary>آیا برندیار به جای من محتوا منتشر می‌کند؟</summary><p>هدف، کمک به تحلیل، ایده‌پردازی و برنامه‌ریزی است. در این پیش‌نمایش، انتشار خودکار محتوا و اتصال واقعی به اینستاگرام فعال نیست.</p></details><details><summary>آیا برای دیدن داشبورد باید حساب بسازم؟</summary><p>در این نسخه می‌توانی پیش‌نمایش داشبورد را بدون ثبت‌نام ببینی. اطلاعات نمایشی نمونه هستند و به صفحه واقعی متصل نیستند.</p></details></div>`;
const pageHero = (label, title, sub) => `<section class="page-hero"><div class="container"><span class="eyebrow">${label}</span><h1>${title}</h1><p>${sub}</p></div></section>`;
const home = () => `<section class="hero"><div class="container hero-grid"><div class="hero-copy"><span class="eyebrow">همراه هوشمند رشد برند شخصی</span><h1 class="display">تخصصت دیده می‌شود،<br><em>وقتی درست روایتش کنی.</em></h1><p class="lead">از سردرگمی در تولید محتوا تا ساختن برندی که مخاطب به آن اعتماد می‌کند؛ جایگاهت را بشناس، مسیرت را پیدا کن و با اطمینان رشد کن.</p><div class="hero-cta"><a class="btn btn-dark" href="#/signup">مسیر رشد من را شروع کن ${icon('arrow')}</a><a class="btn btn-outline" href="#/app">دیدن پیش‌نمایش محصول</a></div><div class="hero-note">${icon('shield')} بدون نیاز به اتصال پیج برای دیدن پیش‌نمایش</div></div><div class="preview-wrap" aria-label="نمونه نمایشی تحلیل برند"><div class="preview-card"><div class="preview-top"><strong>تصویر کلی برند شما</strong><span>نمونه نمایشی</span></div><div class="preview-heading">امتیاز سلامت برند</div><div class="preview-score"><div class="score-ring"><span>74<small>از 100</small></span></div><div class="mini-bars"><div>جایگاه تخصصی<i><b style="width:88%"></b></i></div><div>کیفیت محتوا<i><b style="width:76%"></b></i></div><div>اعتمادسازی<i><b style="width:59%"></b></i></div></div></div><div class="preview-tip"><strong>فرصت رشد شما:</strong> روایت تجربه‌های واقعی‌ات می‌تواند اعتماد مخاطبان را بیشتر کند.</div></div><div class="float-note">${icon('check')} از تحلیل تا اقدام، کنار تو</div></div></div></section><div class="trust-bar"><div class="container trust-inner"><strong>برای کسانی که از دانششان محتوا می‌سازند</strong><span>مدرس‌ها</span><span>مربی‌ها</span><span>تولیدکنندگان محتوای آموزشی</span></div></div><section class="section" id="features"><div class="container"><div class="section-heading"><span class="eyebrow">همه چیز از یک جا شروع می‌شود</span><h2 class="section-title">فقط محتوا نساز؛ <em>یک برند بساز.</em></h2><p class="section-subtitle">ابزارهای درست را کنار هم گذاشته‌ایم تا بین تحلیل کردن، تصمیم گرفتن و اجرا کردن گم نشوی.</p></div>${featureCards}</div></section><section class="section soft"><div class="container split"><div class="insight-art"><div class="insight-sheet"><strong>از تشخیص مسئله تا قدم بعدی</strong><div class="insight-row"><span>نقطه قوت</span><strong>تخصص واضح</strong></div><div class="insight-row"><span>فرصت رشد</span><strong>اعتمادسازی</strong></div><div class="insight-row"><span>قدم پیشنهادی</span><strong>بازنویسی بیو</strong></div></div></div><div><span class="eyebrow">وضوح به جای حدس و گمان</span><h2 class="section-title">بدان کجایی. <em>بدان بعدش چه کار کنی.</em></h2><p class="section-subtitle">رشد برند شخصی قرار نیست مجموعه‌ای از توصیه‌های پراکنده باشد. اول مسئله را پیدا کن، بعد روی اقدام‌هایی تمرکز کن که بیشترین اثر را دارند.</p><ul class="check-list"><li>${icon('check')} تصویری روشن از نقاط قوت و ضعف</li><li>${icon('check')} اولویت‌بندی کارها متناسب با مرحله رشد</li><li>${icon('check')} ایده‌های محتوایی برای تبدیل تخصص به اعتماد</li></ul><a class="btn btn-dark" href="#/how-it-works">ببین چطور کار می‌کند ${icon('arrow')}</a></div></div></section><section class="section light"><div class="container"><div class="section-heading center"><span class="eyebrow">مسیر ساده، نتیجه هدفمند</span><h2 class="section-title">از همین‌جا <em>شروع کن.</em></h2><p class="section-subtitle">بدون نیاز به دانستن اصطلاحات پیچیده بازاریابی.</p></div>${steps}</div></section>${cta}`;
function pricingCards(){return `<div class="pricing-grid"><article class="price-card"><span class="pill">برای شروع</span><h3>رایگان</h3><p>برای شناخت مسیر و دیدن امکانات پایه محصول.</p><div class="price">0 <small>تومان</small></div><a href="#/signup" class="btn btn-outline">شروع رایگان</a><ul><li>${icon('check')} آشنایی با مسیر ساخت برند</li><li>${icon('check')} دسترسی به امکانات پایه پس از راه‌اندازی</li><li>${icon('check')} بدون نیاز به پرداخت برای شروع</li></ul></article><article class="price-card featured"><span class="pill">برای رشد جدی‌تر</span><h3>حرفه‌ای</h3><p>برای مدرس‌هایی که می‌خواهند مسیر رشدشان را منظم پیش ببرند.</p><div class="price">7,990,000 <small>تومان / ماه</small></div><a href="#/signup" class="btn btn-accent">انتخاب طرح حرفه‌ای ${icon('arrow')}</a><ul><li>${icon('check')} تحلیل جامع پرسونال برند</li><li>${icon('check')} نقشه راه رشد اختصاصی</li><li>${icon('check')} ایده‌های محتوایی متناسب با تخصص</li><li>${icon('check')} اولویت‌بندی فرصت‌های بهبود</li></ul></article><article class="price-card custom"><span class="pill">متناسب با نیاز شما</span><h3>سفارشی</h3><p>برای تیم‌ها و مجموعه‌های آموزشی با نیازهای متفاوت.</p><div class="price price-custom">توافقی <small>پس از بررسی نیازها</small></div><a href="#/signup" class="btn btn-outline">ثبت درخواست همکاری ${icon('arrow')}</a><ul><li>${icon('check')} بررسی نیازهای کسب‌وکار شما</li><li>${icon('check')} طراحی مسیر متناسب با اهداف تیم</li><li>${icon('check')} تعیین امکانات و قیمت پس از گفتگو</li></ul></article></div><p class="pricing-note">این صفحه پیش‌نمایش محصول است؛ ثبت‌نام و پرداخت هنوز فعال نشده‌اند و ثبت درخواست همکاری نیز فعلاً نمایشی است.</p>`}
const pages = {
  '': home,
  'features': () => `${pageHero('امکانات برندیار','هر چیزی که برای ساخت برندت لازم داری','از تحلیل جایگاه امروزت تا پیدا کردن ایده و برداشتن قدم بعدی، همه چیز در یک مسیر منسجم.') }<section class="section"><div class="container">${featureCards}</div></section><section class="section soft"><div class="container split"><div><span class="eyebrow">تصمیم‌های بهتر</span><h2 class="section-title">داده‌ها را به <em>اقدام تبدیل کن.</em></h2><p class="section-subtitle">فقط یک عدد و نمودار نمی‌بینی؛ برای هر بخش از برندت می‌فهمی کدام فرصت رشد، توجه بیشتری می‌خواهد.</p><ul class="check-list"><li>${icon('check')} ارزیابی جایگاه تخصصی و کیفیت محتوا</li><li>${icon('check')} ایده‌های متناسب با هدف مخاطب</li><li>${icon('check')} مسیر رشد مرحله‌بندی‌شده</li></ul></div><div class="insight-art"><div class="insight-sheet"><strong>گزارش نمونه</strong><div class="insight-row"><span>تخصص و جایگاه‌سازی</span><strong>88%</strong></div><div class="insight-row"><span>کیفیت محتوا</span><strong>76%</strong></div><div class="insight-row"><span>اعتمادسازی و فروش</span><strong>59%</strong></div></div></div></div></section>${cta}`,
  'how-it-works': () => `${pageHero('چطور کار می‌کند؟','از تخصص تو تا برندی ماندگار','یک مسیر ساده و مرحله‌به‌مرحله برای تبدیل دانش به محتوایی که دیده و به خاطر سپرده شود.') }<section class="section light"><div class="container">${steps}</div></section><section class="section soft"><div class="container split"><div class="insight-art"><div class="insight-sheet"><strong>قدم‌های رشد برند</strong><div class="insight-row"><span>1. شناخت جایگاه</span><strong>شروع</strong></div><div class="insight-row"><span>2. ساخت اعتماد</span><strong>اولویت فعلی</strong></div><div class="insight-row"><span>3. تبدیل مخاطب</span><strong>قدم بعد</strong></div></div></div><div><span class="eyebrow">از برنامه تا عمل</span><h2 class="section-title">هر مرحله، <em>یک قدم روشن.</em></h2><p class="section-subtitle">وقتی بدانید مخاطبتان چه چیزی از شما می‌خواهد، تصمیم‌گیری درباره محتوا راحت‌تر می‌شود. برندیار کمک می‌کند اولویت‌ها را واضح ببینید.</p><a href="#/app" class="btn btn-dark">دیدن پیش‌نمایش داشبورد ${icon('arrow')}</a></div></div></section>${cta}`,
  'pricing': () => `${pageHero('تعرفه‌ها','سرمایه‌گذاری روی برندی که می‌سازی','با طرح رایگان مسیرت را شروع کن و زمانی که آماده بودی سراغ امکانات حرفه‌ای برو.') }<section class="section"><div class="container">${pricingCards()}</div></section><section class="section soft"><div class="container"><div class="section-heading center"><h2 class="section-title">سؤالی درباره طرح‌ها داری؟</h2></div>${faq}</div></section>${cta}`,
  'faq': () => `${pageHero('سؤالات متداول','جواب سؤال‌هایت اینجاست','پیش از شروع، با خیال راحت درباره مسیر و امکانات برندیار بیشتر بدان.') }<section class="section"><div class="container">${faq}</div></section>${cta}`,
  'about': () => `${pageHero('درباره برندیار','برند شخصی، از خودت شروع می‌شود','قرار نیست برای دیده شدن شبیه دیگران شوی؛ کافی است ارزش واقعی‌ات را واضح‌تر نشان دهی.') }<section class="section"><div class="container about-grid"><article class="white-card"><span class="eyebrow">مسئله‌ای که می‌شناسیم</span><h2>از کجا شروع کنم؟</h2><p class="section-subtitle">خیلی از مدرس‌ها تخصص دارند اما برای نمایش آن، ساخت اعتماد و تبدیل مخاطب به مشتری مسیر مشخصی ندارند. تولید محتوای بیشتر، بدون جهت‌گیری درست، همیشه جواب نیست.</p></article><article class="white-card"><span class="eyebrow">چیزی که می‌خواهیم بسازیم</span><h2>یک همراه در تمام مسیر</h2><p class="section-subtitle">برندیار برای کمک به شناخت برند فعلی، شناسایی فرصت‌ها و تبدیل پیشنهادها به یک نقشه راه قابل اجرا طراحی شده است؛ از عیب‌یابی تا ایده‌پردازی.</p></article></div></section>${cta}`,
  'login': () => authPage(false),
  'signup': () => authPage(true)
};
function authPage(signup){return `<section class="form-page"><div class="auth-card"><h1>${signup?'برای ساخت برندت آماده‌ای؟':'خوش آمدی به برندیار'}</h1><p>${signup?'شروع مسیر رشد از همین‌جاست.':'برای ورود به فضای کاری، اطلاعات حسابت را وارد کن.'}</p><div class="notice">${signup?'ثبت‌نام هنوز فعال نیست.':'ورود کارکنان مجاز با رمز عبور و تأیید دومرحله‌ای انجام می‌شود؛ حساب کاربران عادی هنوز راه‌اندازی نشده است.'} <a href="#/app" class="dashboard-link">دیدن داشبورد نمونه ${icon('arrow')}</a></div><form id="auth-form">${signup?'<div class="field"><label for="name">نام و نام خانوادگی</label><input id="name" name="name" type="text" autocomplete="name" required placeholder="نام شما"></div>':''}<div class="field"><label for="email">ایمیل</label><input id="email" name="email" type="email" autocomplete="email" required placeholder="name@example.com"></div><div class="field"><label for="password">رمز عبور</label><input id="password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="8" required placeholder="حداقل 8 کاراکتر">${signup?'<small>برای نسخه نهایی، رمز عبور حداقل 8 کاراکتر خواهد بود.</small>':''}</div><button class="btn btn-dark" type="submit">${signup?'ایجاد حساب':'ورود به حساب'} ${icon('arrow')}</button><div class="form-feedback" id="form-feedback" role="status" aria-live="polite"></div></form><div class="auth-bottom">${signup?'قبلاً حساب ساخته‌ای؟ <a href="#/login">وارد شو</a>':'حساب نداری؟ <a href="#/signup">شروع رایگان</a>'}</div></div></section>`}
const bars = [['تخصص و جایگاه‌سازی',88],['کیفیت و ارزش محتوا',76],['ارتباط با مخاطب',72],['اعتمادسازی و فروش',59]];
const scorePanel = `<article class="panel"><h2>تحلیل سلامت پرسونال برند</h2><p>نمونه‌ای از ارزیابی جایگاه و فرصت‌های رشد</p><div class="score-panel-body"><div class="score-ring"><span>74<small>از 100</small></span></div><div class="bar-list">${bars.map(([label,value])=>`<div class="bar-item"><span>${label}</span><strong>${value}%</strong><div class="track"><i style="width:${value}%"></i></div></div>`).join('')}</div></div></article>`;
const actionsPanel = `<article class="panel"><h2>اقدام‌های پیشنهادی</h2><p>از مهم‌ترین فرصت‌ها شروع کن</p><div class="action-item">${icon('check')}<div><strong>بازنویسی بیو با تمرکز بر ارزش پیشنهادی</strong><small>اولویت بالا · حدود 5 دقیقه</small></div></div><div class="action-item">${icon('check')}<div><strong>روایت یک تجربه واقعی از تدریس</strong><small>مناسب برای اعتمادسازی</small></div></div><div class="action-item">${icon('check')}<div><strong>طراحی برنامه انتشار هفتگی</strong><small>برای افزایش ثبات محتوا</small></div></div></article>`;
const ideas = [['3 اشتباهی که درآمد مدرس‌های آنلاین را متوقف می‌کند','ریلز آموزشی · افزایش ذخیره و اشتراک‌گذاری'],['پشت صحنه ساخت دوره؛ از ایده تا اولین فروش','کاروسل داستانی · اعتمادسازی'],['سؤال‌هایی که قبل از خرید دوره باید بپرسی','استوری تعاملی · شناخت نیاز مخاطب'],['چطور اولین شاگردم را پیدا کردم؟','روایت شخصی · ارتباط با مخاطب']];
function ideaRows(items){let saved=[];try{saved=JSON.parse(localStorage.getItem('brandyar-saved-ideas')||'[]')}catch{}if(!Array.isArray(saved))saved=[];return items.map(([title,desc])=>`<div class="idea-item"><span class="idea-icon">${icon('idea')}</span><div><strong>${title}</strong><small>${desc}</small></div><button type="button" class="save-idea" data-save="${ideas.findIndex(i=>i[0]===title)}" ${saved.includes(title)?'disabled':''}>${saved.includes(title)?'ذخیره شد':'ذخیره'}</button></div>`).join('')}
const roadmapPanel = `<article class="panel"><h2>نقشه راه رشد</h2><p>نمونه‌ای از مسیر مرحله‌ای برند شخصی</p><div class="road-step done"><strong>تعریف جایگاه برند</strong><small>مرحله اول</small></div><div class="road-step current"><strong>ساخت اعتبار و اعتماد</strong><small>مرحله دوم · اولویت فعلی</small></div><div class="road-step"><strong>تبدیل مخاطب به مشتری</strong><small>مرحله سوم</small></div><div class="road-step"><strong>مقیاس‌پذیری برند</strong><small>مرحله چهارم</small></div></article>`;
const appHeading = (title, sub) => `<div class="app-heading"><h1>${title}</h1><p>${sub}</p></div>`;
